import{c as d,Q as r,j as e,m as a}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-指令系统","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-指令系统"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/CPU与指令系统/指令系统.md","filePath":"综合知识/系统基础/计算机组成/CPU与指令系统/指令系统.md","lastUpdated":null}'),n={name:"综合知识/系统基础/计算机组成/CPU与指令系统/指令系统.md"};function o(s,t,l,h,i,g){return r(),e("div",null,[...t[0]||(t[0]=[a('<h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="指令系统-★" tabindex="-1">指令系统 ★ <a class="header-anchor" href="#指令系统-★" aria-label="Permalink to &quot;指令系统 ★&quot;">​</a></h3><h4 id="指令组成与执行" tabindex="-1">指令组成与执行 <a class="header-anchor" href="#指令组成与执行" aria-label="Permalink to &quot;指令组成与执行&quot;">​</a></h4><blockquote><p>一条指令 = <strong>操作码</strong>（决定操作类型）+ <strong>地址码</strong>（操作数地址）。整条指令以二进制编码存放。</p></blockquote><p><strong>执行三阶段</strong>：取指令（PC→地址总线，从内存取）→ 分析指令（ID 解析操作码）→ 执行指令。</p><h4 id="寻址方式" tabindex="-1">寻址方式 <a class="header-anchor" href="#寻址方式" aria-label="Permalink to &quot;寻址方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>顺序寻址</strong></td><td>一条接一条顺序执行</td><td>下一条地址由 PC 给出</td></tr><tr><td><strong>跳跃寻址</strong></td><td>下条地址由本条指令直接给出</td><td>PC 内容相应改变</td></tr></tbody></table><p><strong>操作数寻址方式：</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th style="text-align:center;">速度</th></tr></thead><tbody><tr><td><strong>立即寻址</strong></td><td>地址码直接包含操作数本身</td><td style="text-align:center;">—</td></tr><tr><td><strong>直接寻址</strong></td><td>地址码是操作数的内存地址</td><td style="text-align:center;">—</td></tr><tr><td><strong>间接寻址</strong></td><td>地址码指向存有操作数地址的单元</td><td style="text-align:center;">慢</td></tr><tr><td><strong>寄存器寻址</strong></td><td>操作数在寄存器中</td><td style="text-align:center;"><strong>最快</strong></td></tr><tr><td><strong>基址寻址</strong></td><td>基址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于静态数据</td></tr><tr><td><strong>变址寻址</strong></td><td>变址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于数组/动态数据</td></tr></tbody></table><h4 id="cisc-vs-risc-★" tabindex="-1">CISC vs RISC ★ <a class="header-anchor" href="#cisc-vs-risc-★" aria-label="Permalink to &quot;CISC vs RISC ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比</th><th>CISC（复杂指令集）</th><th>RISC（精简指令集）</th></tr></thead><tbody><tr><td>指令数量</td><td>多</td><td>少</td></tr><tr><td>指令长度</td><td><strong>可变</strong></td><td>固定</td></tr><tr><td>实现方式</td><td>微程序控制</td><td><strong>组合逻辑</strong>（硬件实现）</td></tr><tr><td>寻址方式</td><td>多样</td><td>少</td></tr><tr><td>寄存器</td><td>少</td><td><strong>大量寄存器</strong></td></tr><tr><td>执行时间</td><td>差别大</td><td>多数单周期</td></tr></tbody></table>',11)])])}const _=d(n,[["render",o]]);export{b as __pageData,_ as default};
